func minPathSum(grid [][]int) int {
	//	边界检查
	var (
		ans = 0
		dp  = make([][]int, len(grid))
	)
	min:= func(x,y int) int{
		if x<=y{
			return x
		}
		return y
	}
	if grid == nil {
		return ans
	}
	//	 dp数据结构构造
	for i := 0; i < len(dp); i++ {
		dp[i] = make([]int, len(grid[i]))
	}
	//dp 初始化
	for i := 0; i < len(grid); i++ {
		for j := 0; j < len(grid[i]); j++ {
			if i == 0 {
				if j==0{
					dp[i][j] = grid[i][j]
				}else{
